functions.showExecutiveBriefApp:
function showExecutiveBriefApp() {
  var out = window.eli.ui.claimOutput();
  if (!out) return;
  out.classList.add("eli-view-enter");

  window._frStep = 0;
  window._frScrubbed = false;
  window._frDataGenerated = false;

  var types = getAgreementTypes();
  window.eli.storage.getAll(STORE_REQUESTERS).then(function(_rows){return (_rows||[]).filter(function(_r){return _r&&typeof _r==="object"&&(!_r.id||String(_r.id).charAt(0)!=="_")})}).then(function (savedReqs) {
    var reqList = (savedReqs || []).slice();
    window._ebSavedReqs = reqList;
    window._frTypes = types;

    _frRenderStage();

    // Single source of truth: window._eliDocType is set on doc load by the
    // regex matcher in initialize(). All tools needing the doc type read
    // from there. Default sentinel "Other" means regex couldn't match —
    // dropdown pre-selects "Other" and user can change it manually.
    if (window._frStep === 0) {
      _frSetDetectedTypeStrict(window._eliDocType || "Other");
    }
  });
}

functions._frSetDetectedTypeStrict:
function _frSetDetectedTypeStrict(detected) {
  var sel = document.getElementById("ebTypeSel");
  if (!sel || window._ebTypeManuallySet || !detected) return;

  // "Other" means the regex couldn't classify — pre-select it silently
  // (no toast — we didn't actually "detect" anything).
  var isUnknown = detected === "Other";

  var found = false;
  for (var i = 0; i < sel.options.length; i++) {
    if (sel.options[i].value.toLowerCase() === detected.toLowerCase()) {
      sel.selectedIndex = i;
      if (!isUnknown) showToast("📄 Detected from document stats: " + sel.options[i].value);
      found = true;
      break;
    }
  }
  if (!found) {
    var opt = document.createElement("option");
    opt.value = detected;
    opt.textContent = detected;
    opt.selected = true;
    sel.appendChild(opt);
    if (!isUnknown) showToast("📄 Detected from document stats: " + detected);
  }
}

functions._frSetStep:
function _frSetStep(step) {
  if (step === 0) window._frScrubbed = false;

  // Save type and requester when moving out of step 0
  // Save type and requester when moving out of step 0
  if (window._frStep === 0 && step > 0) {
    var sel = document.getElementById("ebTypeSel");
    if (sel) window._ebType = sel.value;
    window._ebRequester = _ebGetRequester(); // We added this line to save the requester
  }

  window._frStep = step;
  _frRenderStage();

  if (step === 2 && !window._frDataGenerated) {
    window._frDataGenerated = true;
    // The UI renders with shimmering placeholders first, then we immediately run the brief.
    setTimeout(function () {
      runExecutiveBrief();
    }, 50);
  }
}

