functions._ebEnsureExecBriefTermsLoaded:
function _ebEnsureExecBriefTermsLoaded() {
  if (window._ebTermsCache) return Promise.resolve(window._ebTermsCache);
  if (window._ebTermsCacheLoading) return window._ebTermsCacheLoading;
  var p = (window.eli && window.eli.storage && typeof window.eli.storage.getAll === "function")
    ? window.eli.storage.getAll("exec_brief_terms")
    : Promise.resolve([]);
  window._ebTermsCacheLoading = p.then(function (rows) {
    var byType = {}, generic = [];
    (rows || []).forEach(function (r) {
      if (!r || !r.id || r.id === "__meta") return;
      if (r.id === "__generic") { generic = r.terms || []; }
      else if (Array.isArray(r.terms)) { byType[r.id] = r.terms; }
    });
    window._ebTermsCache = { byType: byType, generic: generic };
    window._ebTermsCacheLoading = null;
    return window._ebTermsCache;
  }).catch(function () {
    window._ebTermsCache = { byType: {}, generic: [] };
    window._ebTermsCacheLoading = null;
    return window._ebTermsCache;
  });
  return window._ebTermsCacheLoading;
}

functions.getExecBriefTerms:
function getExecBriefTerms(type) {
  var c = window._ebTermsCache || { byType: {}, generic: [] };
  if (type && c.byType[type] && c.byType[type].length) return c.byType[type].slice();
  return (c.generic || []).slice();
}

