functions._ebToBold:
function _ebToBold(s) {
  return String(s)
    .replace(/[A-Z]/g, function (c) {
      return String.fromCodePoint(0x1d400 + (c.charCodeAt(0) - 0x41));
    })
    .replace(/[a-z]/g, function (c) {
      return String.fromCodePoint(0x1d41a + (c.charCodeAt(0) - 0x61));
    })
    .replace(/[0-9]/g, function (c) {
      return String.fromCodePoint(0x1d7ce + (c.charCodeAt(0) - 0x30));
    });
}

functions._ebExtractCpRef:
function _ebExtractCpRef(callback) {
  if (window._ebData && typeof window._ebData.cpRef === "string") {
    callback(window._ebData.cpRef);
    return;
  }
  try {
    Word.run(function (context) {
      var body = context.document.body;
      body.load("text");
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        var footerLoads = [];
        sections.items.forEach(function (sec) {
          ["Primary", "FirstPage", "EvenPages"].forEach(function (kind) {
            try {
              var f = sec.getFooter(kind);
              f.load("text");
              footerLoads.push(f);
            } catch (e) { }
          });
        });
        return context.sync().then(function () {
          var refRegex = /CP\s*Ref(?:erence)?\s*[:#]?\s*([A-Za-z]?-?\s*[A-Za-z0-9][A-Za-z0-9\-_/]*)/i;
          // Match full multi-segment refs like "A-2026-9333-OC".
          // The previous `\b(A-\d{3,})\b` truncated at the word
          // boundary between the first digit group and the next hyphen
          // → returned "A-2026" instead of the full code.
          var altRegex = /\b(A-\d{3,}(?:-[A-Za-z0-9]+)*)\b/;
          var sources = [body.text || ""];
          footerLoads.forEach(function (f) {
            try {
              sources.push(f.text || "");
            } catch (e) { }
          });
          var found = "";
          for (var i = 0; i < sources.length && !found; i++) {
            var m = sources[i].match(refRegex);
            if (m && m[1]) {
              found = m[1].replace(/\s+/g, "").trim();
              break;
            }
            var m2 = sources[i].match(altRegex);
            if (m2 && m2[1]) {
              found = m2[1].trim();
              break;
            }
          }
          if (window._ebData) window._ebData.cpRef = found;
          callback(found);
        });
      });
    }).catch(function () {
      callback("");
    });
  } catch (e) {
    callback("");
  }
}

functions.getAcceptedDraftText:
function getAcceptedDraftText(context, maxChars) {
  var ooxmlResult = context.document.body.getOoxml();
  return context.sync().then(function () {
    var raw = ooxmlResult.value || "";
    raw = raw.replace(/<w:del\b[^>]*>[\s\S]*?<\/w:del>/g, "");
    raw = raw.replace(/<w:del\b[^>]*\/>/g, "");
    raw = raw.replace(/<w:moveFrom\b[^>]*>[\s\S]*?<\/w:moveFrom>/g, "");
    raw = raw.replace(/<w:ins\b[^>]*>([\s\S]*?)<\/w:ins>/g, "$1");
    raw = raw.replace(/<w:moveTo\b[^>]*>([\s\S]*?)<\/w:moveTo>/g, "$1");
    var matches = raw.match(/<w:t[^>]*>([\s\S]*?)<\/w:t>/g) || [];
    var text = matches
      .map(function (m) {
        return m.replace(/<[^>]+>/g, "");
      })
      .join(" ")
      .replace(/&amp;/g, "&")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/\s+/g, " ")
      .trim();
    if (maxChars && text.length > maxChars) text = text.substring(0, maxChars);
    return text;
  });
}

functions.runExecutiveBrief:
function runExecutiveBrief() {
  showToast("⏳ Running final audit generation...");
  var typeSel = document.getElementById("ebTypeSel");
  var type = typeSel ? typeSel.value : window._ebType;
  if (!type) return;
  var existing = window._ebData || _ebBuildEmptyData(type);
  // Defensive — _ebBuildEmptyData always returns the right shape, but
  // window._ebData might be set elsewhere with a partial object.
  if (!existing || typeof existing !== "object") existing = { overview: "", commitments: [] };
  if (!Array.isArray(existing.commitments)) existing.commitments = [];
  var keyTerms = existing.commitments.map(function (c) {
    return c && c.title;
  }).filter(Boolean);
  if (!keyTerms.length) keyTerms = getExecBriefTerms(type) || [];
  _ebShowGenerating();

  var templatePromise = Promise.resolve(null);
  if (keyTerms.indexOf("Major Deviations from Standard Agreement") > -1) {
    templatePromise = window.eli.storage.getAll(STORE_TEMPLATES).then(function(_rows){return (_rows||[]).filter(function(_r){return _r&&typeof _r==="object"&&(!_r.id||String(_r.id).charAt(0)!=="_")})})
      .then(function (templates) {
        templates = templates || [];
        var match = null;
        for (var i = 0; i < templates.length; i++) {
          if (templates[i].type === type) {
            match = templates[i];
            break;
          }
        }
        if (!match) {
          var searchName =
            type === "Non-Disclosure Agreement" ? "NDA" : type === "Material Transfer Agreement" ? "MTA" : type;
          for (var i = 0; i < templates.length; i++) {
            if (templates[i].name && templates[i].name.toLowerCase().indexOf(searchName.toLowerCase()) > -1) {
              match = templates[i];
              break;
            }
          }
        }
        return match;
      })
      .catch(function () {
        return null;
      });
  }

  templatePromise.then(function (templateData) {
    Word.run(function (context) {
      return getAcceptedDraftText(context, 100000).then(function (docText) {
        var keyTermsList = keyTerms.map(function (t, i) { return i + 1 + ". " + t; }).join("\n");
        var templateBlock = (templateData && templateData.content)
          ? "STANDARD TEMPLATE:\n" + templateData.content + "\n\n"
          : "";
        var prompt = formatPrompt("execBriefSummary", {
          type: type,
          keyTermsList: keyTermsList,
          templateBlock: templateBlock,
          docText: docText,
        }, "You are a Senior Legal Liaison at Colgate-Palmolive. Read the agreement excerpt below and produce a factual executive brief for the business requester to approve before execution.\n\nAGREEMENT TYPE: {{type}}\n\nREQUIRED OUTPUT (raw JSON only, no markdown):\n{\n  \"overview\": \"2-3 sentence factual summary of what this agreement does and the parties involved.\",\n  \"commitments\": [\n    { \"title\": \"<exact key term title>\", \"details\": \"2-4 sentence factual summary of both parties' obligations under this term.\", \"ref\": \"<section/clause reference, e.g. 'Sec 5.2' or 'Ex A' or — if not specified>\", \"quote\": \"<8-20 word VERBATIM excerpt copied EXACTLY from the document that anchors this clause, used by a search function to locate it; empty string if not addressed>\", \"severity\": \"Success | Medium | Low\" }\n  ]\n}\n\nKEY TERMS TO COVER (one commitment per term in this exact order):\n{{keyTermsList}}\n\nRULES:\n- Be matter-of-fact. No legal analysis, no recommendations — just clearly explain what each party committed to.\n- If a key term is not addressed in the document, set details to 'Not addressed in this agreement.', ref to —, and quote to ''.\n- 'severity' is contextual: Success = favorable/standard, Medium = noteworthy, Low = minor administrative.\n- Use the EXACT title text given.\n- 'details' MUST be substantive (3+ full sentences) covering scope, each party's obligations, and any thresholds, dates, or exceptions. The 'quote' field is separate metadata and does NOT replace, summarize, or shorten any detail content.\n- 'quote' MUST be a contiguous verbatim excerpt copied character-for-character from the document — no paraphrasing, no quote marks added — so it can be located by a literal search.\n- DEFAULT-RULE INTERPRETATIONS — when a term is silent, explain what the silence means in practice:\n    • 'Major Deviations from Standard Agreement': Compare the DOCUMENT EXCERPT against the STANDARD TEMPLATE (if provided below). Summarize only substantive, material deviations. State the differences strictly factually without any commentary, judgment, or subjective words like 'notable', 'restrictive', 'unreasonable', or 'concerning'. Completely ignore changes to text originally enclosed in brackets (e.g. party names, dates, specific purpose fields) and formatting changes.\n    • 'Conflicts of Interest' / 'Non-Solicit / Conflicts': if the agreement does NOT restrict the third party from working with others on related subject matter, set details to: 'Not addressed in this agreement. By default, the third party is free to work for other parties (including competitors) on related subject matter during the term of this agreement.' Set ref to — and quote to ''.\n    • 'Publication Control' / 'Publication Rights': if silent, default rule is the third party may publish freely; explain that.\n    • 'IP Ownership of Results' / 'IP & Deliverables': if silent, default rule is each party owns what it creates; explain that.\n    • 'Confidentiality Duration': if silent, default rule is no time limit on confidentiality obligations; explain that.\n\n{{templateBlock}}DOCUMENT EXCERPT:\n{{docText}}");
        return window.eli.ai.completeJSON(prompt, null, { jsonMode: true }).then(function (aiData) {
          // eli.ai.completeJSON returns the already-parsed object —
          // don't wrap it in _ebParseAiJson (would no-op on objects and
          // crash on the indexOf fallback if completeJSON ever degrades
          // to a string-y response).
          aiData = aiData || {};
          if (!Array.isArray(aiData.commitments)) aiData.commitments = [];
          var aiByTitle = {};
          aiData.commitments.forEach(function (c) {
            if (c && c.title) aiByTitle[String(c.title).toLowerCase().trim()] = c;
          });
          var merged = {
            overview: aiData.overview || existing.overview || "",
            commitments: existing.commitments.map(function (orig) {
              var match = aiByTitle[String(orig.title).toLowerCase().trim()];
              return {
                title: orig.title,
                details: (match && match.details) || orig.details || "",
                ref: (match && match.ref) || orig.ref || "—",
                quote: (match && match.quote) || orig.quote || "",
                severity: (match && match.severity) || orig.severity || "Low",
                included: orig.included !== false,
              };
            }),
          };
          renderExecutiveBriefResults(merged, type, false);
          try {
            if (window.eli && window.eli.activity && window.eli.activity.add) {
              var _ebIncluded = (merged.commitments || []).filter(function (c) {
                return c.included !== false;
              }).length;
              window.eli.activity.add({
                type: "approval-brief",
                icon: "💼",
                label: "Final Review",
                summary: type + " — " + _ebIncluded + " review item" + (_ebIncluded === 1 ? "" : "s"),
                payload: { data: merged, type: type },
              });
            }
          } catch (_) { }
        });
      });
    }).catch(function (e) {
      _ebRestoreFromGenerating();
      showToast("⚠️ Brief failed: " + (e.message || e));
    });
  });
}

